INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-001', '01', 'Magenta Plum Printed Three Piece', 'ম্যাজেন্টা ও প্লাম প্রিন্টেড থ্রি-পিস', 'magenta-plum-printed-three-piece', 2350, 'high', 'ম্যাজেন্টা ও প্লামের আকর্ষণীয় বৈপরীত্যে সাজানো এই থ্রি-পিসে আছে সাদা-গোলাপি ফুল, পেইসলি মোটিফ ও ডেকোরেটিভ বর্ডার। উজ্জ্বল ফুশিয়া সলিড কাপড় এবং ট্যাসেলসহ প্রিন্টেড ওড়না পুরো সেটে যোগ করে প্রাণবন্ত একটি ফিনিশ।', 'প্লাম বেসে ফ্লোরাল-পেইসলি প্রিন্ট ও বর্ডার', 'উজ্জ্বল ফুশিয়া/পিংক সলিড কাপড়', 'ম্যাজেন্টা-প্লাম প্রিন্ট, ফুলের মোটিফ ও ট্যাসেল', 'Not specified', 'Unconfirmed; separate sleeve cloth mentioned', '#8E3B66', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-002', '02', 'Emerald Teal Batik', 'এমেরাল্ড টিল বাটিক থ্রি-পিস', 'emerald-teal-batik', 2150, 'high', 'কালো ও আইভরি রঙের অ্যাবস্ট্রাক্ট বাটিক-অনুপ্রাণিত নকশায় একটি স্বতন্ত্র লুক। টিল-সবুজ টাই-ডাই ঘরানার ওড়নার রাস্ট বর্ডার এবং টেরাকোটা রঙের সলিড কাপড় যোগ করেছে সাহসী, মার্জিত কনট্রাস্ট।', 'কালো/চারকোল বেসে আইভরি ফ্লোরাল ও জ্যামিতিক প্রিন্ট', 'টেরাকোটা/রাস্ট সলিড কাপড়', 'টিল-সবুজ স্ট্রাইপ ও রাস্ট বর্ডার', 'Not specified', 'Unconfirmed', '#1F6E63', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-003', '02', 'Dusty Mauve Floral Batik', 'ডাস্টি মভ ফ্লোরাল বাটিক থ্রি-পিস', 'dusty-mauve-floral-batik', 2050, 'high', 'ডাস্টি মভের কোমল রঙে অফ-হোয়াইট ফুল এবং বড় বৃত্তাকার বাটিক মোটিফের পরিমিত সৌন্দর্য। একই টোনের সলিড কাপড় ও সূক্ষ্ম ফ্লোরাল প্রিন্টের ট্যাসেলযুক্ত ওড়নায় তৈরি হয়েছে সহজ, রুচিশীল থ্রি-পিস কম্বিনেশন।', 'ডাস্টি মভে সাদা ফুল ও গোলাকার বাটিক মোটিফ', 'ম্যাচিং ডাস্টি মভ সলিড কাপড়', 'মভ ফ্লোরাল প্রিন্ট, সূক্ষ্ম টেক্সচার ও ট্যাসেল', 'Not specified', 'Unconfirmed', '#A87C8F', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-004', '03', 'Forest Elegance', 'ফরেস্ট এলিগ্যান্স', 'forest-elegance', 1850, 'medium', 'মাটির রঙের উষ্ণতা ও ফরেস্ট গ্রিনের গভীরতা মিলেছে বোটানিক্যাল বাটিক-অনুপ্রাণিত নকশায়। ড্রেস ম্যাটেরিয়ালের সঙ্গে বাদামি সলিড কাপড় ও সবুজ গ্রেডিয়েন্ট ওড়নার পাতার ছাপ এবং ট্যাসেল পুরো লুকে আনে প্রাকৃতিক আবহ।', 'আর্থি ব্রাউন ও ফরেস্ট গ্রিন বোটানিক্যাল প্রিন্ট', 'সলিড ব্রাউন কাপড়', 'সবুজ গ্রেডিয়েন্ট ওড়না, ক্রিম বোটানিক্যাল ছাপ', 'Batik collection (technique not certified)', 'Dress materials shown; tailoring not confirmed', '#3E5E3A', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-005', '03', 'Fuchsia Noir', 'ফুশিয়া নোয়ার', 'fuchsia-noir', 1700, 'high', 'তীক্ষ্ণ ফুশিয়া-পিংক ও চারকোলের ড্রামাটিক কনট্রাস্টে নজরকাড়া বাটিক থ্রি-পিস ম্যাটেরিয়াল। কামিজের ওপর গোলাপি ও সাদা ফুলেল ছাপ, সঙ্গে সলিড ফুশিয়া কাপড় এবং গাঢ় থেকে উজ্জ্বল রঙে পরিবর্তিত ওড়না।', 'চারকোল/কালো বেসে ফুশিয়া ও সাদা ফ্লোরাল প্রিন্ট', 'উজ্জ্বল ফুশিয়া সলিড কাপড়', 'ফুশিয়া-চারকোল গ্রেডিয়েন্ট ও ফুলের মোটিফ', 'Batik collection (technique not certified)', 'Dress materials shown; tailoring not confirmed', '#B0326E', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-006', '03', 'Mustard Noir', 'মাস্টার্ড নোয়ার', 'mustard-noir', 1650, 'high', 'উজ্জ্বল মাস্টার্ড ও গাঢ় চারকোলের দুই-টোন প্যালেটে ক্লাসিক বাটিক ঘরানার নকশা। ছোট ছোট বোটানিক্যাল রিপিট প্রিন্টের সঙ্গে সলিড হলুদ কাপড় এবং মাস্টার্ড থেকে চারকোলের গ্রেডিয়েন্ট ওড়না একটি সুষম সেট তৈরি করে।', 'চারকোল বেসে মাস্টার্ড বোটানিক্যাল রিপিট', 'সলিড মাস্টার্ড হলুদ কাপড়', 'হলুদ-চারকোল গ্রেডিয়েন্ট, বোটানিক্যাল মোটিফ', 'Batik collection (technique not certified)', 'Dress materials shown; tailoring not confirmed', '#C0912F', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-007', '03', 'Burgundy Sunset', 'বারগান্ডি সানসেট', 'burgundy-sunset', 1750, 'medium', 'বারগান্ডি ও সানসেট-মাস্টার্ডের উষ্ণ মেলবন্ধনে ব্যতিক্রমী টাই-ডাই অনুপ্রাণিত ড্রেস ম্যাটেরিয়াল। গোলাকার বাটিক স্ট্যাম্পের মতো মোটিফ এবং ওড়নার বিস্তৃত রঙের পরিবর্তন ডিজাইনটিকে দেয় আলাদা চরিত্র।', 'গাঢ় বারগান্ডি বেসে মাস্টার্ড বৃত্তাকার মোটিফ', 'ম্যাচিং কাপড়; রঙের বরাদ্দ যাচাই প্রয়োজন', 'বারগান্ডি-মাস্টার্ড টাই-ডাই ও গ্রেডিয়েন্ট', 'Batik collection (technique not certified)', 'Dress materials shown; tailoring not confirmed', '#7E2F3C', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-008', '04', 'Navy Royal Bloom', 'নেভি রয়্যাল ব্লুম', 'navy-royal-bloom', 1750, 'high', 'গভীর নেভি ব্লু বেসে সাদা অলঙ্করণধর্মী কেন্দ্রীয় নকশা এবং উষ্ণ বর্ডারের ক্লাসিক কনট্রাস্ট। হলুদ ফুলেল ওড়না ও গাঢ় সলিড কাপড়ের সঙ্গে এই আনস্টিচড থ্রি-পিসে তৈরি হয় রাজকীয়, স্মার্ট এথনিক অনুভূতি।', 'নেভিতে সাদা অর্নামেন্টাল কেন্দ্রীয় প্যানেল ও বর্ডার', 'সলিড গাঢ় নেভি/প্রায় কালো কাপড়', 'হলুদ ফুল, গাঢ় বর্ডারযুক্ত প্রিন্টেড ওড়না', 'Swiss lawn; digital print (seller-described, unverified)', 'Unstitched - explicitly stated', '#2C4470', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-009', '04', 'Autumn Floral Elegance', 'অটাম ফ্লোরাল এলিগ্যান্স', 'autumn-floral-elegance', 1700, 'high', 'হালকা স্টোন-বেইজ বেসে শরতের ফুলের প্রিন্ট ও মাঝখানে সরু মাস্টার্ড প্যানেল। রাস্ট সলিড কাপড় এবং বহুরঙা ফ্লোরাল-বর্ডার ওড়নার সমন্বয় এই আনস্টিচড সেটকে করেছে সতেজ ও প্রাণবন্ত।', 'স্টোন/বেইজে ছোট ফুল ও মাস্টার্ড সেন্টার প্যানেল', 'সলিড রাস্ট/ব্রাউন কাপড়', 'ফুলেল প্রিন্ট, পিংক ও কালো অর্নামেন্টাল বর্ডার', 'Swiss lawn; digital print (seller-described, unverified)', 'Unstitched - explicitly stated', '#B4652F', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-010', '04', 'Midnight Teal Heritage', 'মিডনাইট টিল হেরিটেজ', 'midnight-teal-heritage', 1650, 'review', 'ডার্ক প্লাম-চারকোল বেসে লম্বালম্বি হেরিটেজ মেডেলিয়ন ও জ্যামিতিক নকশার অনন্য বিন্যাস। অ্যাকোয়া-টিল সলিড কাপড় এবং গাঢ় অর্নামেন্টাল প্রিন্টের ওড়না সেটটিকে দিয়েছে আধুনিক ঐতিহ্যবাহী আবহ।', 'ডার্ক প্লাম-চারকোলে উল্লম্ব মেডেলিয়ন প্রিন্ট', 'সলিড অ্যাকোয়া-টিল কাপড়', 'গাঢ় রঙে অর্নামেন্টাল ও পেইসলি বর্ডার', 'Swiss lawn; digital print (seller-described, unverified)', 'Unstitched - explicitly stated', '#1F4E4A', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-011', '04', 'Olive Garden Bloom', 'অলিভ গার্ডেন ব্লুম', 'olive-garden-bloom', 1850, 'high', 'অলিভ গ্রিন বেসের ওপর ছড়িয়ে থাকা রঙিন ফুলের বুকে একটি নরম, প্রাকৃতিক স্টাইল। হালকা স্ট্রাইপ ও বড় ফ্লোরাল ওড়নার সঙ্গে ডিপ গ্রিন সলিড কাপড় মিলিয়ে এই আনস্টিচড সেটে আছে শান্ত কিন্তু স্বতন্ত্র উপস্থিতি।', 'অলিভ গ্রিনে রঙিন ফুলের বুকে', 'সলিড ডিপ গ্রিন কাপড়', 'হালকা স্ট্রাইপ, বড় ফুল ও কনট্রাস্ট বর্ডার', 'Swiss lawn; digital print (seller-described, unverified)', 'Unstitched - explicitly stated', '#6B6B33', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-012', '04', 'Coral Geometric Bloom', 'কোরাল জিওমেট্রিক ব্লুম', 'coral-geometric-bloom', 1650, 'review', 'কোরাল-পিংক বেসে ট্রায়াঙ্গেল ও হেক্সাগোনাল জ্যামিতিক প্রিন্টের আধুনিক কম্বিনেশন। সলিড কোরাল কাপড় এবং ফুল, লাইন-আর্ট ও জ্যামিতিক বর্ডারের ওড়না মিলে একটি উজ্জ্বল, সমন্বিত আনস্টিচড থ্রি-পিস।', 'কোরাল-পিংক ত্রিভুজ ও হেক্সাগোনাল মোটিফ', 'সলিড কোরাল-পিংক কাপড়', 'ফ্লোরাল ও জ্যামিতিক বর্ডারসহ কোরাল ওড়না', 'Swiss lawn; digital print (seller-described, unverified)', 'Unstitched - explicitly stated', '#D06A4E', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-013', '04', 'Crimson Floral Mosaic', 'ক্রিমসন ফ্লোরাল মোজাইক', 'crimson-floral-mosaic', 1800, 'review', 'গাঢ় চারকোল বেসে ক্রিমসন কেন্দ্রীয় প্যানেল ও ছোট ছোট বহুরঙা ফুলের নকশা। মভ-গ্রে ফ্লোরাল ওড়না এবং টোপ/মোকা সলিড কাপড়ের মিশেলে এই আনস্টিচড থ্রি-পিসে আসে সমৃদ্ধ, আর্টিস্টিক লুক।', 'কালো/চারকোলে লাল কেন্দ্রীয় প্যানেল ও রঙিন ফুল', 'সলিড টোপ/মোকা কাপড়', 'মভ-গ্রে ফ্লোরাল প্রিন্ট ও কালো বর্ডার', 'Swiss lawn; digital print (seller-described, unverified)', 'Unstitched - explicitly stated', '#9E2B33', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-014', '05', 'Golden Mustard Mirror Elegance', 'গোল্ডেন মাস্টার্ড মিরর এলিগ্যান্স', 'golden-mustard-mirror-elegance', 2050, 'high', 'উজ্জ্বল গোল্ডেন-মাস্টার্ডে ডায়মন্ড গ্রিড এবং আয়নার মতো ঝলমলে অ্যাকসেন্টের নজরকাড়া ডিজাইন। বারগান্ডি প্রিন্টেড সালোয়ার কাপড় ও বিস্তারিত বর্ডারের মাস্টার্ড ওড়না সেটে যোগ করে উৎসবমুখর কনট্রাস্ট।', 'মাস্টার্ডে ডায়মন্ড গ্রিড ও মিরর-লুক অ্যাকসেন্ট', 'বারগান্ডি/ম্যাজেন্টা প্যাটার্নের কাপড়', 'মাস্টার্ড, সাদা ফুলেল স্ট্রাইপ ও ডিটেইলড বর্ডার', 'Cotton (catalog label only; exact composition not verified)', 'Ready-made per cover; size/fit unverified', '#C6952B', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-015', '05', 'Midnight Black Ethnic Charm', 'মিডনাইট ব্ল্যাক এথনিক চার্ম', 'midnight-black-ethnic-charm', 2150, 'high', 'গাঢ় ব্ল্যাক-চারকোল বেসে কমলা-লাল জ্যামিতিক চেইন ও নেকলাইনের প্রিন্ট। বারগান্ডি-টু-ব্ল্যাক ওড়নার ছোট হলুদ মোটিফ এবং কালো-কমলা জ্যামিতিক প্যাটার্নের সালোয়ার কাপড়ের সঙ্গে তৈরি হয়েছে শক্তিশালী এথনিক লুক।', 'কালো বেসে কমলা-লাল জ্যামিতিক চেইন প্রিন্ট', 'কালো-কমলা হেক্সাগোনাল প্যাটার্নের কাপড়', 'বারগান্ডি-কালো গ্রেডিয়েন্ট ও জ্যামিতিক বর্ডার', 'Cotton (catalog label only; exact composition not verified)', 'Ready-made per cover; size/fit unverified', '#3A3A44', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-016', '05', 'Fuchsia Bloom Aqua Delight', 'ফুশিয়া ব্লুম অ্যাকোয়া ডিলাইট', 'fuchsia-bloom-aqua-delight', 1950, 'high', 'ফুশিয়া-পিংকের উজ্জ্বলতায় অ্যাকোয়া রঙের নেকলাইন ও ফ্লোরাল-জ্যামিতিক ছাপ। হালকা অ্যাকোয়া সালোয়ার কাপড় এবং ফুশিয়া ওড়নার নীল-সাদা বর্ডারে সৃষ্টি হয়েছে তরুণ, প্রাণবন্ত রঙের মেলবন্ধন।', 'ফুশিয়া-পিংকে অ্যাকোয়া নেকলাইন ও ছোট ফ্লোরাল মোটিফ', 'হালকা অ্যাকোয়া, ম্যাজেন্টা ক্ষুদ্র ফুলের ছাপ', 'ফুশিয়া, নীল-সাদা ফুলেল ও জ্যামিতিক বর্ডার', 'Cotton (catalog label only; exact composition not verified)', 'Ready-made per cover; size/fit unverified', '#C13B78', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-017', '05', 'Electric Blue Mirror Blossom', 'ইলেকট্রিক ব্লু মিরর ব্লসম', 'electric-blue-mirror-blossom', 2250, 'high', 'ইলেকট্রিক ব্লু রঙে ডায়মন্ড গ্রিড ও হলুদ মিরর-লুক অ্যাকসেন্টের প্রাণবন্ত নকশা। নেভি সালোয়ার কাপড়ের হালকা জিগজ্যাগ প্যাটার্ন আর নীল-পিংক বর্ডারের আকাশি ওড়নায় সুন্দর কনট্রাস্ট।', 'ইলেকট্রিক ব্লু, গ্রিড ও ঝলমলে-দেখানো ডিটেইল', 'নেভিতে হালকা জিগজ্যাগ/রেখা প্যাটার্ন', 'আকাশি নীল ওড়না, নীল-পিংক ফুলেল বর্ডার', 'Cotton (catalog label only; exact composition not verified)', 'Ready-made per cover; size/fit unverified', '#2E5FA3', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-018', '05', 'Sand Beige Floral Grace', 'স্যান্ড বেইজ ফ্লোরাল গ্রেস', 'sand-beige-floral-grace', 2450, 'high', 'হালকা স্যান্ড-বেইজ রঙে সূক্ষ্ম ফুলেল নকশা, রঙিন নেকলাইন বোতাম ও পরিমিত ডিজাইনের শান্ত সৌন্দর্য। ডিপ পার্পল সালোয়ার কাপড় এবং সূক্ষ্ম সাদা লাইনওয়ার্কের বেইজ ওড়নায় স্টাইলটি হয়ে উঠেছে রুচিশীল।', 'স্যান্ড-বেইজে সূক্ষ্ম ফ্লোরাল প্রিন্ট ও রঙিন বোতাম', 'ডিপ পার্পল ফুলেল/অর্নামেন্টাল প্যাটার্ন', 'বেইজে সূক্ষ্ম সাদা লাইনওয়ার্ক ও বৃত্তাকার মোটিফ', 'Cotton (catalog label only; exact composition not verified)', 'Ready-made per cover; size/fit unverified', '#B99C74', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, price_bdt = EXCLUDED.price_bdt, description_bn = EXCLUDED.description_bn;
